export function getWordsByLesson(lessonId: string): VocabEntry[] {
  return WORDS.filter((w) => w.lesson_id === lessonId);
}

export function getWordsByIds(ids: string[]): VocabEntry[] {
  return ids.map((id) => WORDS.find((w) => w.id === id)).filter(Boolean) as VocabEntry[];
}

export function getBattleWords(tier: DifficultyTier): VocabEntry[] {
  const pool = BATTLE_POOLS.find((p) => p.tier === tier);
  if (!pool) return [];
  return getWordsByIds(pool.word_ids);
}

export function getLessonById(id: string): Lesson | undefined {
  return LESSONS.find((l) => l.id === id);
}

export function getFirstLesson(): Lesson {
  return LESSONS[0];
}

export function getNextLesson(currentLessonId: string): Lesson | undefined {
  const current = LESSONS.find((l) => l.id === currentLessonId);
  if (!current) return undefined;
  return LESSONS[current.order];
}

export function getReviewWords(lessonId: string): VocabEntry[] {
  const lesson = LESSONS.find((l) => l.id === lessonId);
  if (!lesson) return [];
  return getWordsByIds(lesson.review_word_ids);
}
